// TestAdminMiddleware_TokenMatrix is the S8 / AC-5 joint: the auth middleware
// resolves Principal{Role: RoleAdmin} for a correct Bearer admin token and
// Principal{Role: RoleClient} for a minted device token (device-pairing D3),
// and short-circuits with a 401 canonical body otherwise — without ever
// invoking the wrapped handler. Asserting the dummy next handler's call count
// proves the side-effect gating (no handler, hence no domain call, runs on a
// miss). The matrix name is retained for test-stability across the
// admin->auth middleware rename (S-roles).
func TestAdminMiddleware_TokenMatrix(t *testing.T) {
	// One real device credential: mint → approve → pick up through the real
	// pairing service, so the middleware's LookupToken branch is exercised
	// against the hash the store actually holds.
	st := openAPIStore(t)
	devices := pairing.NewService(st, nil)
	ctx := context.Background()
	reqRow, err := devices.CreateRequest(ctx, "10.0.0.1")
	if err != nil {
		t.Fatalf("CreateRequest: %v", err)
	}
	if _, err := devices.Approve(ctx, reqRow.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	out, err := devices.Wait(ctx, reqRow.ID)
	if err != nil || out.Token == "" {
		t.Fatalf("Wait: outcome=%+v err=%v (want the raw device token once)", out, err)
	}
	deviceToken := out.Token

	cases := []struct {
		name       string
		auth       string
		devices    *pairing.Service
		wantStatus int
		wantCalled bool
		wantRole   Role
	}{
		{"no_header", "", nil, http.StatusUnauthorized, false, ""},
		{"wrong_scheme", "Basic dXNlcjpwYXNz", nil, http.StatusUnauthorized, false, ""},
		{"wrong_token", "Bearer " + adminToken + "-wrong", nil, http.StatusUnauthorized, false, ""},
		{"correct_token", "Bearer " + adminToken, nil, http.StatusOK, true, RoleAdmin},
		{"device_token_hit", "Bearer " + deviceToken, devices, http.StatusOK, true, RoleClient},
		{"device_token_nil_service", "Bearer " + deviceToken, nil, http.StatusUnauthorized, false, ""},
		{"unknown_device_token", "Bearer " + deviceToken + "-wrong", devices, http.StatusUnauthorized, false, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var called bool
			var principal Principal
			var hasPrincipal bool
			next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				called = true
				principal, hasPrincipal = principalFromContext(r.Context())
				w.WriteHeader(http.StatusOK)
			})
			wrapped := authMiddleware(adminToken, tc.devices)(next)

			req := httptest.NewRequest(http.MethodGet, "/api/v1/items", nil)
			if tc.auth != "" {
				req.Header.Set("Authorization", tc.auth)
			}
			rec := httptest.NewRecorder()
			wrapped.ServeHTTP(rec, req)

			if rec.Code != tc.wantStatus {
				t.Fatalf("status = %d, want %d", rec.Code, tc.wantStatus)
			}
			if called != tc.wantCalled {
				t.Fatalf("wrapped handler called = %v, want %v", called, tc.wantCalled)
			}
			if tc.wantCalled {
				if !hasPrincipal || principal.Role != tc.wantRole {
					t.Fatalf("expected Principal{Role:%s} in context; got %+v (present=%v)", tc.wantRole, principal, hasPrincipal)
				}
				return
			}
			// 401 path: canonical error body present.
			if eb := decodeError(t, rec.Result()); eb.Error.Code != "unauthenticated" {
				t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
			}
		})
	}
}

// TestRequireRole covers the S-roles middleware-side authZ joint (T04 B2/B3):
// requireRole admits a principal whose Role is in the allowed set and 403-denes
// every other role, including unknown/empty (default-deny — INV-default-deny),
// and fails closed when the allowed set is empty. The matrix is set over a
// synthetic Principal injected straight into the request context (RoleClient is
// test-only here — no resolver mints it yet). next-called is asserted on both
// paths so the short-circuit is proven.
func TestRequireRole(t *testing.T) {
	cases := []struct {
		name       string
		role       Role
		allow      []Role
		wantStatus int
		wantCalled bool
	}{
		{"admin_admitted_by_admin_only", RoleAdmin, []Role{RoleAdmin}, http.StatusOK, true},
		{"client_denied_by_admin_only", RoleClient, []Role{RoleAdmin}, http.StatusForbidden, false},
		{"admin_admitted_by_admin_client", RoleAdmin, []Role{RoleAdmin, RoleClient}, http.StatusOK, true},
		{"client_admitted_by_admin_client", RoleClient, []Role{RoleAdmin, RoleClient}, http.StatusOK, true},
		{"unknown_role_denied", Role("superuser"), []Role{RoleAdmin}, http.StatusForbidden, false},
		{"empty_role_denied_default_deny", Role(""), []Role{RoleAdmin}, http.StatusForbidden, false},
		{"empty_allow_set_fails_closed", RoleAdmin, []Role{}, http.StatusForbidden, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var called bool
			next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				called = true
				w.WriteHeader(http.StatusOK)
			})
			wrapped := requireRole(tc.allow...)(next)

			req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/status", nil)
			ctx := context.WithValue(req.Context(), principalKey{}, Principal{Role: tc.role})
			req = req.WithContext(ctx)
			rec := httptest.NewRecorder()
			wrapped.ServeHTTP(rec, req)

			if rec.Code != tc.wantStatus {
				t.Fatalf("status = %d, want %d", rec.Code, tc.wantStatus)
			}
			if called != tc.wantCalled {
				t.Fatalf("next called = %v, want %v", called, tc.wantCalled)
			}
			if !tc.wantCalled {
				if eb := decodeError(t, rec.Result()); eb.Error.Code != "forbidden" {
					t.Fatalf("error code = %q, want forbidden", eb.Error.Code)
				}
			}
		})
	}
}

// TestBearerCredentials covers the scheme-extraction helper at the boundary.
// Stubbing it to return "" (its zero value) flips every matrix case to 401 — so
// this test catches a broken extractor the matrix would also catch, redundantly
// but explicitly over the parser's own input space.
func TestBearerCredentials(t *testing.T) {
	cases := []struct {
		header string
		want   string
	}{
		{"", ""},
		{"Bearer ", ""},
		{"Basic xyz", ""},
		{"Bearer secret-token", "secret-token"},
		{"Bearer  spaced", " spaced"},
	}
	for _, tc := range cases {
		if got := bearerCredentials(tc.header); got != tc.want {
			t.Errorf("bearerCredentials(%q) = %q, want %q", tc.header, got, tc.want)
		}
	}
}
